## 第 2 段：授权状态文件定位器

扫描安装目录、用户数据目录、ProgramData 和注册表，找出程序存放授权状态的文件，并解析其结构。

```python
#!/usr/bin/env python3
# licenseloc.py — 只读扫描，定位授权状态文件并解析结构
# 用法:
#   python licenseloc.py --install "C:\Program Files\Vendor\Product"
#   python licenseloc.py --install "..." --report license_report.json
#
# 读取策略: 只 open(..., 'rb') 读前 4096 字节。不写入、不修改、不解密。

import json, os, re, sys, hashlib, sqlite3, argparse, zipfile, struct
from pathlib import Path
from datetime import datetime, timezone

# 文件名/后缀候选 —— 授权状态最常见的落点
NAME_HINTS = [
    "license", "licence", "lic", "activation", "activate", "regist",
    "auth", "serial", "key", "entitlement", "seat", "subscri",
    "session", "token", "credential", "perm", "settings", "config",
    "v2c", "c2v", "r2v", "offline", "backup", "receipt", "verify",
]
EXT_HINTS = [
    ".lic", ".license", ".dat", ".json", ".xml", ".ini", ".cfg",
    ".conf", ".config", ".reg", ".db", ".sqlite", ".blob", ".bin",
    ".store", ".state", ".idx", ".enc", ".sig", ".pem", ".pfx",
]

# 二进制里常见的授权标记串
BIN_MARKERS = [
    b"LicenseKey", b"LicenseID", b"ProductKey", b"SerialNumber",
    b"ActivationId", b"MachineId", b"DeviceId", b"HWID", b"BindingId",
    b"NotBefore", b"NotAfter", b"GracePeriod", b"TrialStart",
    b"Expired", b"TrialExpired", b"IsLicensed", b"IsActivated",
    b"SubscriptionEnd", b"Entitlement", b"SignatureAlg",
]

MACHINE_ID_PATTERNS = [
    re.compile(rb"[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}"),
    re.compile(rb"\b[0-9A-Fa-f]{32}\b"),           # md5 裸串
    re.compile(rb"\b[0-9A-Fa-f]{40}\b"),           # sha1 裸串
    re.compile(rb"\b[0-9A-Fa-f]{64}\b"),           # sha256 裸串
    re.compile(rb"\b\d{4}-\d{4}-\d{4}-\d{4}\b"),   # 分组卡密
    re.compile(rb"\b[A-Z0-9]{5}(?:-[A-Z0-9]{5}){3,7}\b", re.I),  # 短块卡密
]

def entropy(data: bytes) -> float:
    if not data: return 0.0
    freq = [0] * 256
    for b in data: freq[b] += 1
    n = len(data)
    return -sum((c / n) * (c and __import__("math").log2(c / n)) for c in freq if c)

def user_dirs():
    home = Path(os.environ.get("USERPROFILE", Path.home()))
    appdata = Path(os.environ.get("APPDATA", home / "AppData/Roaming"))
    local = Path(os.environ.get("LOCALAPPDATA", home / "AppData/Local"))
    out = [appdata, local]
    pd = Path(os.environ.get("ProgramData", "C:/ProgramData"))
    if pd.exists(): out.append(pd)
    return out

def scan_dir(root: Path, max_files=40000, max_size=8 * 1024 * 1024):
    results, seen = [], 0
    for dirpath, dirnames, filenames in os.walk(root, onerror=lambda e: None):
        dirnames[:] = [d for d in dirnames
                        if d.lower() not in {"windows", "$recycle.bin", "system volume information"}]
        for fn in filenames:
            seen += 1
            if seen > max_files: return results
            low = fn.lower()
            if not (any(h in low for h in NAME_HINTS) or
                    Path(low).suffix in EXT_HINTS):
                continue
            p = Path(dirpath) / fn
            try:
                st = p.stat()
                if st.st_size > max_size: continue
                head = p.open("rb").read(4096)
            except Exception:
                continue
            markers = [m.decode() for m in BIN_MARKERS if m in head]
            ids = []
            for pat in MACHINE_ID_PATTERNS:
                for mt in pat.findall(head)[:3]:
                    ids.append(mt.decode("ascii", "ignore"))
            results.append({
                "path": str(p),
                "size": st.st_size,
                "mtime": datetime.fromtimestamp(st.st_mtime, timezone.utc).isoformat(),
                "entropy": round(entropy(head), 2),
                "markers": markers,
                "embedded_ids": ids[:5],
            })
    return results

def parse_structure(path: str):
    """识别容器类型：JSON / INI / SQLite / ZIP / 注册表 hive / 不明二进制"""
    try:
        head = open(path, "rb").read(4096)
    except Exception as e:
        return {"container": "unreadable", "error": str(e)}
    if head[:2] == b"PK":
        try:
            with zipfile.ZipFile(path) as z:
                return {"container": "zip", "entries": z.namelist()[:50]}
        except Exception as e:
            return {"container": "zip-broken", "error": str(e)}
    if head[:15] == b"SQLite format 3":
        try:
            con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
            tabs = [r[0] for r in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'")]
            dump = {}
            for t in tabs[:10]:
                cols = [r[1] for r in con.execute(f'PRAGMA table_info("{t}")')]
                rows = con.execute(f'SELECT * FROM "{t}" LIMIT 5').fetchall()
                dump[t] = {"columns": cols, "sample": rows}
            con.close()
            return {"container": "sqlite", "tables": dump}
        except Exception as e:
            return {"container": "sqlite-broken", "error": str(e)}
    if head[:4] == b"regf":
        return {"container": "registry-hive"}
    try:
        txt = head.decode("utf-8").lstrip()
        if txt[:1] in "{[":
            full = json.load(open(path, "r", encoding="utf-8", errors="replace"))
            return {"container": "json", "top_keys": list(full)[:50],
                    "redacted": _redact(full)}
    except Exception:
        pass
    try:
        raw = open(path, "r", encoding="utf-8", errors="replace").read(8192)
        if re.search(r"^\s*\[[^\]]+\]\s*$", raw, re.M) or "=" in raw:
            keys = re.findall(r"^\s*([A-Za-z_][\w\-. ]*)\s*=", raw, re.M)
            return {"container": "ini-like", "keys": keys[:60]}
    except Exception:
        pass
    return {"container": "opaque",
            "head_hex": head[:64].hex(),
            "hint": "高熵且无标记 → 可能是加密/签名blob，需第 6 段看它何时被读"}

SENSITIVE = re.compile(r"(key|licen|serial|token|secret|password|signature)", re.I)

def _redact(obj, depth=0):
    """报告里对疑似密钥字段做部分遮蔽，方便你比对而不外泄"""
    if depth > 4: return "<deep>"
    i
